import { useState } from "react";

function Square({value, onSquareClick, squareIndex}) {
	let myClassName = "square";
	switch (value)
	{
		case 'X' :
			myClassName.concat(" black-pawn");
			break;
		case 'O' :
			myClassName.concat(" white-pawn");
			break;
		default :
			break;
	}
	return (
		<button 
		className= { myClassName }
		onClick={onSquareClick}>
			{}
		</button>
	)
}

function Board({xIsNext, squares, onPlay}) {

	function handleClick( i ) {
		if (squares[i])
			return ;

		const nextSquares = squares.slice();
		if (xIsNext)
			nextSquares[i] = "X";
		else
			nextSquares[i] = "O";
		onPlay(nextSquares);
	}

	// display White : <pawnCount> Black : <pawnCount>
	//		Next player : <nextPlayer>


	const initializeBoard = () => {
		return (
			Array(8)
			.fill(null)
			.map((_, rowIndex) => (
				<div className="board-row" key={rowIndex}>
					{
						Array(8)
						.fill(null)
						.map((_, colIndex) => {
							const squareIndex = rowIndex * 3 + colIndex;
							return (
								<Square
								key={squareIndex}
								value={squares[squareIndex]}
								squareIndex={squareIndex}
								onSquareClick={() => handleClick(squareIndex)}
								/>
							);
						})
					}
				</div>
			))
		);
	};

	return ( 
		<div className="board">
			<div className="status">{status}</div>
			{initializeBoard()}
		</div>
	);
}

export default function Game() {

	const [ascending, setAscending ] = useState(false);
	const [history, setHistory] = useState([Array(64).fill(null)]);
	const [currentMove, setCurrentMove] = useState(0);
	const xIsNext = currentMove % 2 === 0;
	const currentSquares = history[currentMove];

	function handlePlay( nextSquares ) {
		const nextHistory = [...history.slice(0, currentMove + 1), nextSquares];
		setHistory(nextHistory);
		setCurrentMove(nextHistory.length - 1);
	}

	function jumpTo(nextMove) {
		setCurrentMove(nextMove);
	}

	const moves = history.map((squares, move) => {

		let description;
		if (move > 0 )
		{
			const prevSquares = history[move - 1];
			let squareIndex = -1;
			for (let i = 0; i < squares.length; i++ )
			{
				if ( squares[i] !== prevSquares[i] )
				{
					squareIndex = i;
					break;
				}
			}
			const rowIndex = Math.floor( squareIndex / 8 ) + 1;
			const colIndex = squareIndex % 8 + 1
			description = `#${move} ${move % 2 === 0 ? "O" : "X"} played [${rowIndex}, ${colIndex}]`;
		} 
		else
			description = "Go to game start";
		return (
			<li key={move}>
				<button onClick={() => jumpTo(move)}>{description}</button>
			</li>
		);
	});

	return (
		<div className="game">
			<div className="game-board">
				<Board xIsNext={xIsNext} squares={currentSquares} onPlay={handlePlay} />
				<span className="move-info">You are at move #{currentMove}</span>
			</div>
			<div className="game-info">
				<button className="toggle-button" onClick={() => setAscending(!ascending)}>
					Reverse
				</button>
				<ol>{ascending ? moves.reverse() : moves}</ol>
			</div>
		</div>
	);
}
